            if (i0 === 2) {
                turn = dx === y0 - oldy && dy === oldx - x0 ? 2 : -2;
            } else if (dx && dy) {
                turn = (dx === dy && y0 === oldy) || (dx !== dy && y0 !== oldy) ? -1 : 1;
            } else {
                turn = (x0 - oldx === y0 - oldy && !dy) || (x0 - oldx !== y0 - oldy && dy) ? 1 : -1;
            }
            turn += game._last_str_turn || 0;
